// Reconstruct progress from saved results so partially played brackets survive reloads.
function playoffScheduleSlots(){
 let pairs=firstRoundPairs(),slots=[];const stages=usesConferencePlayoffs()?['First round','Conference semifinal','Conference final','Championship']:['Semifinal','Championship'];
 for(const stage of stages){const round=pairs.map(pair=>{const ids=[...pair].sort((a,b)=>rank().findIndex(t=>t.id===a)-rank().findIndex(t=>t.id===b));return {stage,pair:ids,result:playoffGames().find(g=>g.stage===stage&&ids.includes(g.a)&&ids.includes(g.b))}});slots.push(...round);if(round.some(s=>!s.result))break;const winners=round.map(s=>s.result.winner);pairs=[];for(let i=0;i<winners.length;i+=2)pairs.push(winners.slice(i,i+2))}return slots;
}
let playoffActionBusy=false;
async function simulatePlayoffGame(a,b,watch=false){
 if(playoffActionBusy||!gmCanAdvance()||state.day!==seasonLength()||state.champion!==null)return;
 const slot=playoffScheduleSlots().find(s=>!s.result&&s.pair[0]===a&&s.pair[1]===b);if(!slot)return;
 playoffActionBusy=true;const before=snapshotState();let game;
 try{ownerTrack();finalizeRegularAwards();watchCapture={day:state.day+1,a,b};try{game=play(a,b,slot.stage)}finally{watchCapture=null}
 if(slot.stage==='Championship'){state.champion=game.winner;if(game.winner===controlledTeamId())state.titles++;ownerFinalize();say(state.teams[game.winner].city+' win the '+state.year+' championship!')}
 if(!await save()){state=before;render();return}render();if(watch){clearTimeout(liveWatchTimer);liveWatch={result:game,index:0,paused:false,speed:leagueRules().playbackSpeed};const dialog=watchDialog();renderWatchGame();if(!dialog.open)dialog.showModal();scheduleWatchTick()}return game;
 }finally{playoffActionBusy=false}
}
playoffs=async function(){if(playoffActionBusy)return;while(state.champion===null){const slot=playoffScheduleSlots().find(s=>!s.result);if(!slot||!await simulatePlayoffGame(...slot.pair))break}};
function viewPlayoffMatchup(a,b){const slot=playoffScheduleSlots().find(s=>s.pair.includes(a)&&s.pair.includes(b));if(!slot)return;const identity=id=>{const t=state.teams[id];return `<div>${teamLogo(t)}<h3>${escapeHTML(t.city+' '+t.name)}</h3><small>${t.w}–${t.l} regular season · ${slot.pair[0]===id?'Home':'Away'}</small></div>`};titleModal('Playoff matchup',`<p>${slot.stage} · ${escapeHTML(teamArena(state.teams[slot.pair[0]]))}</p><div class="matchup-identities">${identity(a)}<span>VS</span>${identity(b)}</div>${matchupComparison(a,b)}<p class="matchup-helper">Regular-season averages and league ranks.</p>`);document.getElementById('profile').classList.add('matchup-dialog')}
postseasonSchedulePanel=function(){const league=scheduleSettings().audience==='league',slots=playoffScheduleSlots().filter(s=>league||s.pair.includes(scheduleTeamId()));return `<section class="panel schedule-postseason"><div class="panelhead"><h2>Playoff games</h2><span>Single elimination</span></div><div class="schedule-list">${slots.map(s=>{const [a,b]=s.pair;return `<article class="league-schedule-game"><strong>${s.stage}</strong><div class="league-matchup">${s.pair.map((id,i)=>`<div>${teamLogo(state.teams[id])}<strong>${escapeHTML(state.teams[id].city+' '+state.teams[id].name)}</strong><small>${i?'AWAY':'HOME'}</small></div>`).join('')}</div><div>${s.result?s.result.sa+'–'+s.result.sb+' · Final':'Upcoming'}</div><div class="schedule-watch-actions">${scheduleSpread(a,b,s.result)}<button onclick="viewPlayoffMatchup(${a},${b})">View matchup</button>${s.result?`<button onclick="showResult(${state.history.indexOf(s.result)})">View results</button>`:`<button onclick="simulatePlayoffGame(${a},${b})">Simulate game</button><button class="primary" onclick="simulatePlayoffGame(${a},${b},true)">Watch live</button>`}</div></article>`}).join('')||'<p class="note">No playoff games for your team. Select Entire league to view the bracket.</p>'}</div><p class="note">The next round appears after every game in the current round is finished.</p><div class="schedule-actions"><button onclick="${state.champion===null?'playoffs()':'newSeason()'}">${state.champion===null?'Simulate remaining playoffs':'Continue offseason'}</button></div></section>`};
